solution.js:
const coffee = 4.1;
const lunch = 12.2;
const bus = 2.7;
const typedAmount = "3";

const budgetCents = 2500;

const totalCents =
  Math.round(coffee * 100) +
  Math.round(lunch * 100) +
  Math.round(bus * 100) +
  Math.round(Number(typedAmount) * 100);

const isOverBudget = totalCents > budgetCents;
const leftCents = budgetCents - totalCents;
console.log(totalCents, isOverBudget, leftCents);
